    HIGGS_ActionResult pendingResult{};pendingResult.structSize=sizeof(pendingResult);CHECK(Service().Result(tap.client,original,pendingResult)==HIGGS_HAND_OK);pendingResult.stage=HIGGS_ACTION_COMPLETED;CHECK(Service().Report(tap.client,pendingResult)==HIGGS_HAND_WRONG_PHASE);const auto pendingSnapshot=Service().CopyPublished();HIGGS_PhysicalRequest physical{};physical.structSize=sizeof(physical);physical.kind=HIGGS_PHYSICAL_RELEASE;physical.physicalHand=1;physical.epoch=pendingSnapshot.epoch;physical.handGeneration=pendingSnapshot.hands[0].generation;physical.grant=pendingSnapshot.hands[0].grant;physical.timeoutMs=100;uint64_t unavailableRequest=999;CHECK(Service().Physical(tap.client,physical,unavailableRequest,start)==HIGGS_HAND_WRONG_PHASE&&unavailableRequest==999);
    Frame(0,start+50000000,output);Frame(Bit(7),start+100000000,output);CHECK(!output&&!tap.executions);Frame(0,start+150000000,output);Frame(Bit(7),start+200000000,output);CHECK(!output&&!tap.executions);Frame(0,start+250000000,output);CHECK(tap.executions==1&&tap.executed.requestId==original);HIGGS_InputRecognition state{};CHECK(Service().CopyInputRecognition(tap.client,original,state)==HIGGS_HAND_OK&&state.stage==HIGGS_RECOGNITION_MATCHED&&state.matchedTaps==3&&state.recognizedFrame.pressed==0);CHECK(tap.observations>0&&tap.actionable==6);CHECK(Service().Unregister(tap.client)==HIGGS_HAND_OK);
    Consumer hold;Setup(hold,"hold",1,HIGGS_GESTURE_HOLD);const auto h=start+1000000000;Frame(Bit(1),h,output);CHECK(hold.submitted==HIGGS_HAND_OK&&!output&&!hold.executions);Frame(Bit(1),h+60000000,output);CHECK(hold.executions==1&&!output);Frame(Bit(1),h+70000000,output);CHECK(hold.executions==1&&!output);Frame(0,h+80000000,output);CHECK(!output);
    Frame(Bit(1),h+100000000,output);const auto timeout=hold.lastRequest;Frame(Bit(1),h+400000000,output);CHECK(hold.executions==1&&!output);const auto copiedTimeout=Service().CopyInputRecognition(hold.client,timeout,state);if(copiedTimeout||state.stage!=HIGGS_RECOGNITION_EXPIRED)std::cerr<<"timeout copy "<<copiedTimeout<<" stage "<<state.stage<<" req "<<timeout<<" submit "<<hold.submitted<<" deadline "<<state.deadlineAtNs<<" frame "<<h+400000000<<"\\n";CHECK(copiedTimeout==HIGGS_HAND_OK&&state.stage==HIGGS_RECOGNITION_EXPIRED);Frame(Bit(1),h+410000000,output);CHECK(!output&&hold.executions==1);Frame(0,h+420000000,output);CHECK(Service().Unregister(hold.client)==HIGGS_HAND_OK);
